/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic done
);
    typedef enum logic [1:0] {IDLE, DATA, STOP, WAIT_STOP} state_t;
    state_t state_r;
    logic [2:0] bit_count_r;

    always_ff @(posedge clk) begin
        if (reset) begin
            state_r <= IDLE;
            bit_count_r <= 3'd0;
            done <= 1'b0;
        end else begin
            done <= 1'b0;
            case (state_r)
                IDLE: begin
                    if ("'!in) begin
                        state_r <= DATA;
                        bit_count_r <= 3'"'d0;
                    end
                end
                DATA: begin
                    if (bit_count_r == 3'd7)
                        state_r <= STOP;
                    else
                        bit_count_r <= bit_count_r + 3'd1;
                end
                STOP: begin
                    if (in) begin
                        done <= 1'b1;
                        state_r <= IDLE;
                    end else begin
                        state_r <= WAIT_STOP;
                    end
                end
                WAIT_STOP: begin
                    if (in)
                        state_r <= IDLE;
                end
                default: begin
                    state_r <= IDLE;
                    bit_count_r <= 3'd0;
                end
            endcase
        end
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv"

